def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda c: sum(row.count(c) for row in grid))

    # Find the full stripe of color 2.
    stripe_row = next((r for r in range(h) if all(x == 2 for x in grid[r])), None)
    stripe_col = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)

    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != 2]
    if not points:
        return out

    if stripe_row is not None:
        line = stripe_row
        min_r = min(r for r, c in points)
        max_r = max(r for r, c in points)
        if max_r < line:
            shift = line - 1 - max_r
            far_edge = min_r + shift - 1
        else:
            shift = line + 1 - min_r
            far_edge = max_r + shift + 1

        for r, c in points:
            out[r][c] = bg
        for r, c in points:
            out[r + shift][c] = grid[r][c]
        if 0 <= far_edge < h:
            out[far_edge] = [8] * w

    elif stripe_col is not None:
        line = stripe_col
        min_c = min(c for r, c in points)
        max_c = max(c for r, c in points)
        if max_c < line:
            shift = line - 1 - max_c
            far_edge = min_c + shift - 1
        else:
            shift = line + 1 - min_c
            far_edge = max_c + shift + 1

        for r, c in points:
            out[r][c] = bg
        for r, c in points:
            out[r][c + shift] = grid[r][c]
        if 0 <= far_edge < w:
            for r in range(h):
                out[r][far_edge] = 8

    return out
